function cloudRectPath(x,y,w,h){return cloudPolygonPath([[x,y],[x+w,y],[x+w,y+h],[x,y+h]])}
function cloudPolygonPath(points){if(!points?.length)return'';const pts=[...points,points[0]],r=10;let d=`M${points[0][0]} ${points[0][1]}`;for(let s=0;s<points.length;s++){const [x1,y1]=pts[s],[x2,y2]=pts[s+1],dx=x2-x1,dy=y2-y1,len=Math.max(1,Math.hypot(dx,dy)),n=Math.max(1,Math.round(len/r));for(let i=1;i<=n;i++){const t0=(i-1)/n,t1=i/n,mx=x1+dx*(t0+t1)/2,my=y1+dy*(t0+t1)/2,px=-dy/len,py=dx/len,bulge=Math.min(5,len/n*.35),ex=x1+dx*t1,ey=y1+dy*t1;d+=` Q${mx+px*bulge} ${my+py*bulge} ${ex} ${ey}`}}return d+' Z'}
function startZoomRect(e,start){const ig=$('#interactionLayer'),r=svgEl('rect',{class:'zoomRect'});ig.appendChild(r);const move=ev=>{const q=svgPoint(ev);r.setAttribute('x',Math.min(start.x,q.x));r.setAttribute('y',Math.min(start.y,q.y));r.setAttribute('width',Math.abs(q.x-start.x));r.setAttribute('height',Math.abs(q.y-start.y))};const up=ev=>{const q=svgPoint(ev),w=Math.abs(q.x-start.x),h=Math.abs(q.y-start.y);window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);if(w>5&&h>5){const a=$('#canvasScroller'),factor=Math.min((a.clientWidth-40)/(w*96/72),(a.clientHeight-40)/(h*96/72));setZoom(factor);requestAnimationFrame(()=>{const cx=(Math.min(start.x,q.x)+w/2)*96/72*state.zoom,cy=(Math.min(start.y,q.y)+h/2)*96/72*state.zoom;a.scrollLeft=Math.max(0,cx-a.clientWidth/2);a.scrollTop=Math.max(0,cy-a.clientHeight/2)})}renderMarkups();setTool('hand')};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)}
