$('#pageSvg').addEventListener('click',e=>{if(!POLY_TYPES.includes(state.tool)||e.detail>1)return;const p=svgPoint(e);if(!state.polyDraft){const m=baseMarkup(state.tool,p);m.points=[[p.x,p.y]];if(state.tool==='hatchFree')m.hatch=state.preset.hatch==='none'?'diag45':state.preset.hatch;if(state.tool==='cloudFree'){m.fill='#fff';m.fillOpacity=0}currentPage().markups.push(m);state.polyDraft=m}else state.polyDraft.points.push([p.x,p.y]);renderMarkups()});
