function finishPolyDraft(select=true){const m=state.polyDraft;if(!m)return;if(m.points.length>1){const a=m.points.at(-1),b=m.points.at(-2);if(Math.hypot(a[0]-b[0],a[1]-b[1])<5)m.points.pop()}const need=m.type==='polyline'?2:3;if(m.points.length<need)currentPage().markups=currentPage().markups.filter(x=>x!==m);else if(select){state.selected=m.id;m.modified=new Date().toISOString()}state.polyDraft=null;render();if(select)setTool('select')}
