$$('[data-preset]').forEach(b=>b.onclick=()=>{if(b.dataset.preset==='reviewRed')Object.assign(state.preset,{stroke:'#d71920',width:2,fill:'#fff',fillOpacity:0,dash:'',hatch:'none',opacity:1});if(b.dataset.preset==='inspectionBlue')Object.assign(state.preset,{stroke:'#0066cc',width:2,fill:'#fff',fillOpacity:0,dash:'',hatch:'none',opacity:1});if(b.dataset.preset==='yellowHighlight')Object.assign(state.preset,{stroke:'#f3c000',width:1,fill:'#ffe000',fillOpacity:.45,dash:'',hatch:'none',opacity:.8});toast('Drawing default updated.')});
function renderLayers(){const box=$('#layerList');if(!box)return;box.innerHTML='';state.layers.forEach(l=>{const row=document.createElement('div');row.className='layerRow';const active=document.createElement('button');active.className=l.id===state.activeLayer?'activeLayer':'';active.textContent=l.id===state.activeLayer?'●':'○';active.title='Make active layer';active.onclick=()=>{state.activeLayer=l.id;renderLayers()};const vis=document.createElement('button');vis.textContent=l.visible===false?'◌':'◉';vis.title=l.visible===false?'Show layer':'Hide layer';vis.onclick=()=>{l.visible=l.visible===false?true:false;if(state.selected&&!isMarkupVisible(selectedMarkup()||{}))state.selected=null;render()};const lock=document.createElement('button');lock.textContent=l.locked?'🔒':'🔓';lock.title=l.locked?'Unlock layer':'Lock layer';lock.onclick=()=>{l.locked=!l.locked;renderLayers();renderSelection()};const name=document.createElement('span');name.className='layerName';name.textContent=l.name;row.append(active,vis,lock,name);box.appendChild(row)});updateProperties()}
$('#addLayer').onclick=()=>{let base='Layer',n=1;while(state.layers.some(l=>l.name===`${base} ${n}`))n++;const id='layer_'+Date.now().toString(36);state.layers.push({id,name:`${base} ${n}`,visible:true,locked:false});state.activeLayer=id;renderLayers();toast(`Created ${base} ${n}.`)};
function fillStamps(id,list,cls=''){const box=$(id);box.innerHTML='';list.forEach(t=>{const b=document.createElement('button');b.className='stampBtn '+cls;b.textContent=t;b.onclick=()=>addStamp(t);box.appendChild(b)})}fillStamps('#stampsInspection',inspection);fillStamps('#stampsSignals',signals,'blue');fillStamps('#stampsSigns',signs,'blue');fillStamps('#stampsTtc',ttc,'orange');
function renderCustomStamps(){const box=$('#stampsCustom');box.innerHTML='';state.customStamps.forEach(s=>{const b=document.createElement('button');b.className='stampBtn customStampBtn';b.innerHTML=`<img src="${s.data}" alt="${esc(s.name)}"><span>${esc(s.name)}</span>`;b.onclick=()=>addStamp(s.name.replace(/\.[^.]+$/,''));box.appendChild(b)})}try{state.customStamps=JSON.parse(localStorage.getItem('nxt_custom_stamps')||'[]')}catch{}renderCustomStamps();
$('#addCustomStamp').onclick=()=>$('#stampOpen').click();$('#stampOpen').onchange=async e=>{const f=e.target.files[0];if(!f)return;state.customStamps.push({name:f.name,data:await fileDataUrl(f)});localStorage.setItem('nxt_custom_stamps',JSON.stringify(state.customStamps));renderCustomStamps();toast('Custom stamp added to local library.')};
function trafficPreview(s){const cls=s.shape==='diamond'?'diamond '+(s.background==='orange'?'orange':''):s.shape==='octagon'?'octagon':s.shape==='triangle'?'triangle':'rectangle '+(s.background==='green'?'green':s.background==='blue'?'blue':'');const text=(s.shape==='octagon'?'STOP':s.shape==='triangle'?'YIELD':s.name).split(/\s+/).slice(0,4).join(' ');return`<div class="trafficSignPreview"><div class="face ${cls}"><span>${esc(text)}</span></div></div>`}
function renderTrafficLibrary(){const q=($('#trafficSearch').value||'').trim().toLowerCase(),cat=$('#trafficCategory').value,box=$('#trafficResults');box.innerHTML='';let items=[];MUTCD_SIGNS.forEach(s=>items.push({...s,itemKind:'sign'}));TEXAS_SIGNS.forEach(s=>items.push({...s,itemKind:'sign'}));TRAFFIC_DEVICES.forEach(s=>items.push({...s,category:'devices',itemKind:'device',source:'2025 TMUTCD Part 6 / TxDOT work-zone standards'}));TXDOT_STANDARDS.forEach(s=>items.push({...s,category:'standards',itemKind:'standard',source:'Current TxDOT Traffic Standards'}));items=items.filter(s=>(cat==='all'||s.category===cat)&&(!q||`${s.code} ${s.name} ${s.source||''} ${s.group||''}`.toLowerCase().includes(q)));items.forEach(s=>{const b=document.createElement('button');if(s.itemKind==='sign'){b.className='trafficCard';b.innerHTML=trafficPreview(s)+`<span class="trafficMeta"><b>${esc(s.code)}</b><strong>${esc(s.name)}</strong><small>${esc(s.source||'')}</small></span>`;b.onclick=()=>addTrafficSign(s)}else if(s.itemKind==='device'){const glyph={cone:'▲',drum:'▥',verticalPanel:'▯',barricade:'☷',barrier:'▰',arrowBoard:'⇢',pcms:'▣',tma:'▱',flagger:'⚑',workVehicle:'▣',trafficFlow:'➜',workZone:'▧',buffer:'⋯'}[s.kind]||'◆';b.className='trafficCard deviceCard';b.innerHTML=`<span class="deviceGlyph">${glyph}</span><span class="trafficMeta"><b>${esc(s.code)}</b><strong>${esc(s.name)}</strong><small>${esc(s.source)}</small></span>`;b.onclick=()=>addTrafficDevice(s)}else{b.className='trafficCard standardCard';b.innerHTML=`<span class="trafficMeta"><b>${esc(s.code)}</b><strong>${esc(s.name)}</strong><small>${esc(s.detail||s.source||'')}</small></span>`;b.onclick=()=>addStandardNote(s)}box.appendChild(b)});const foot=document.createElement('div');foot.className='trafficMore';foot.textContent=`${items.length} matching reference item${items.length===1?'':'s'} · click an item to place a plan-reference object`;box.appendChild(foot)}
$('#trafficSearch').oninput=renderTrafficLibrary;$('#trafficCategory').onchange=renderTrafficLibrary;
HATCH_LIBRARY.forEach(h=>{const o=document.createElement('option');o.value=h.id;o.textContent=`${h.family} — ${h.name}`;$('#propHatch').appendChild(o)});const none=document.createElement('option');none.value='none';none.textContent='None';$('#propHatch').insertBefore(none,$('#propHatch').firstChild);
$('#newPage').onclick=()=>$('#modalBackdrop').classList.remove('hidden');$('#cancelModal').onclick=()=>$('#modalBackdrop').classList.add('hidden');$('#createPage').onclick=()=>{const [w,h,name]=$('#sheetSize').value.split(',');state.pages.push(newPage(+w,+h,name));state.pageIndex=state.pages.length-1;state.selected=null;$('#modalBackdrop').classList.add('hidden');render();fitPage()};
$('#importImage').onclick=()=>$('#imageOpen').click();$('#imageOpen').onchange=async e=>{const f=e.target.files[0];if(!f)return;const data=await fileDataUrl(f),img=new Image();img.onload=()=>{const landscape=img.width>=img.height,p=newPage(landscape?792:612,landscape?612:792,'Imported Image');p.bg={data,name:f.name};state.pages.push(p);state.pageIndex=state.pages.length-1;render();fitPage()};img.src=data};
function fileDataUrl(f){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)})}
$('#btnOpen').onclick=()=>$('#fileOpen').click();$('#fileOpen').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.name.toLowerCase().endsWith('.nxp')){loadProject(JSON.parse(await f.text()));return}if(f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf')){const url=URL.createObjectURL(f);state.pdfMode=true;$('#pdfFrame').src=url+'#toolbar=1&navpanes=0&view=FitH';$('#pdfFrame').classList.remove('hidden');$('#pdfNotice').classList.remove('hidden');$('#canvasScroller').classList.add('hidden');state.projectName=f.name;$('#docTitle').textContent=f.name;closePalettes();setTool('hand');toast('Opened PDF in native-view mode.');return}if(f.type.startsWith('image/')){$('#imageOpen').files=e.target.files;$('#imageOpen').dispatchEvent(new Event('change'))}};$('#closePdfMode').onclick=()=>{state.pdfMode=false;$('#pdfFrame').classList.add('hidden');$('#pdfNotice').classList.add('hidden');$('#canvasScroller').classList.remove('hidden');setTool('hand');fitPage()};
$('#btnSaveProject').onclick=()=>{const data={format:'NXT Gen Plans Project',version:'0.1-R2',projectName:state.projectName,pages:state.pages,preset:state.preset,layers:state.layers,activeLayer:state.activeLayer};download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),(state.projectName.replace(/\.pdf$/i,'')||'NXT_Gen_Plans')+'.nxp')};function loadProject(d){if(!d||!Array.isArray(d.pages))return toast('Not a valid NXT project file.');state.pages=d.pages;state.projectName=d.projectName||'NXT Gen Plans';state.preset={...state.preset,...(d.preset||{})};if(Array.isArray(d.layers)&&d.layers.length)state.layers=d.layers;state.activeLayer=d.activeLayer||state.layers[0]?.id||'default';state.pageIndex=0;state.selected=null;state.pdfMode=false;$('#pdfFrame').classList.add('hidden');$('#pdfNotice').classList.add('hidden');$('#canvasScroller').classList.remove('hidden');render();fitPage();toast('Project loaded.')}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1200)}
$('#btnExportPdf').onclick=async()=>{if(state.pdfMode)return toast('0.1 PDF export supports NXT plan-canvas pages. Imported-PDF annotation/export requires the next PDF-engine checkpoint.');finishInlineEdit();toast('Rendering flattened Adobe-compatible PDF…');try{const pages=[];for(let i=0;i<state.pages.length;i++)pages.push(await rasterPage(i));download(new Blob([buildPdf(pages)],{type:'application/pdf'}),(state.projectName.replace(/\.[^.]+$/,'')||'NXT_Gen_Plans')+'_review.pdf');toast('PDF exported.')}catch(err){console.error(err);toast('PDF export failed: '+err.message)}};
async function rasterPage(i){const prev=state.pageIndex,sel=state.selected;state.pageIndex=i;state.selected=null;render();await new Promise(r=>setTimeout(r,25));const p=currentPage(),svg=$('#pageSvg').cloneNode(true);svg.querySelector('#interactionLayer').innerHTML='';svg.setAttribute('width',p.w*2);svg.setAttribute('height',p.h*2);const xml=new XMLSerializer().serializeToString(svg),blob=new Blob([xml],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=url});const c=document.createElement('canvas');c.width=Math.round(p.w*2);c.height=Math.round(p.h*2);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);const jpg=base64Bytes(c.toDataURL('image/jpeg',.94).split(',')[1]);state.pageIndex=prev;state.selected=sel;render();return{w:p.w,h:p.h,jpg,iw:c.width,ih:c.height}}
function base64Bytes(s){const bin=atob(s),a=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);return a}
function buildPdf(pages){const enc=new TextEncoder(),parts=[],offsets=[0];let len=0;const push=x=>{const b=typeof x==='string'?enc.encode(x):x;parts.push(b);len+=b.length};push('%PDF-1.7\n%âãÏÓ\n');const objects=[];objects[1]='<< /Type /Catalog /Pages 2 0 R >>';const kids=[];let obj=3;for(const p of pages){const pageObj=obj++,contentObj=obj++,imgObj=obj++;kids.push(`${pageObj} 0 R`);objects[pageObj]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${p.w} ${p.h}] /Resources << /XObject << /Im0 ${imgObj} 0 R >> >> /Contents ${contentObj} 0 R >>`;const stream=`q\n${p.w} 0 0 ${p.h} 0 0 cm\n/Im0 Do\nQ\n`;objects[contentObj]={dict:`<< /Length ${enc.encode(stream).length} >>`,stream:enc.encode(stream)};objects[imgObj]={dict:`<< /Type /XObject /Subtype /Image /Width ${p.iw} /Height ${p.ih} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${p.jpg.length} >>`,stream:p.jpg}}objects[2]=`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${pages.length} >>`;for(let i=1;i<objects.length;i++){offsets[i]=len;push(`${i} 0 obj\n`);const o=objects[i];if(typeof o==='string')push(o+'\nendobj\n');else{push(o.dict+'\nstream\n');push(o.stream);push('\nendstream\nendobj\n')}}const xref=len;push(`xref\n0 ${objects.length}\n0000000000 65535 f \n`);for(let i=1;i<objects.length;i++)push(String(offsets[i]).padStart(10,'0')+' 00000 n \n');push(`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);const out=new Uint8Array(len);let pos=0;for(const b of parts){out.set(b,pos);pos+=b.length}return out}
function setZoom(z){state.zoom=Math.max(.05,Math.min(8,z));const zt=Math.round(state.zoom*100)+'%';$('#zoomSelect').value=[...$('#zoomSelect').options].some(o=>o.value===zt)?zt:'';render()}
function fitPage(){if(state.pdfMode)return;const p=currentPage(),a=$('#canvasScroller');setZoom(Math.min((a.clientWidth-55)/(p.w*96/72),(a.clientHeight-55)/(p.h*96/72)))}function fitWidth(){if(state.pdfMode)return;const p=currentPage(),a=$('#canvasScroller');setZoom((a.clientWidth-45)/(p.w*96/72))}
$('#zoomIn').onclick=()=>setZoom(state.zoom*1.25);$('#zoomOut').onclick=()=>setZoom(state.zoom/1.25);$('#fitPage').onclick=fitPage;$('#fitWidth').onclick=fitWidth;$('#actualSize').onclick=()=>setZoom(1);$('#zoomSelect').onchange=e=>{const n=parseFloat(e.target.value);if(n)setZoom(n/100)};
const sc=$('#canvasScroller');sc.addEventListener('pointerdown',e=>{if(state.tool!=='hand'||e.button!==0)return;state.pan={x:e.clientX,y:e.clientY,l:sc.scrollLeft,t:sc.scrollTop};sc.classList.add('panning');e.preventDefault()});window.addEventListener('pointermove',e=>{if(!state.pan)return;sc.scrollLeft=state.pan.l-(e.clientX-state.pan.x);sc.scrollTop=state.pan.t-(e.clientY-state.pan.y)});window.addEventListener('pointerup',()=>{state.pan=null;sc.classList.remove('panning')});sc.addEventListener('wheel',e=>{if(e.ctrlKey){e.preventDefault();const old=state.zoom;setZoom(state.zoom*(e.deltaY<0?1.12:.89));const ratio=state.zoom/old;sc.scrollLeft=(sc.scrollLeft+e.offsetX)*ratio-e.offsetX;sc.scrollTop=(sc.scrollTop+e.offsetY)*ratio-e.offsetY}},{passive:false});
function updateStatus(){const p=currentPage();$('#statusPage').textContent=`Page ${state.pageIndex+1} / ${state.pages.length}`;$('#statusSize').textContent=p.name;$('#statusZoom').textContent=Math.round(state.zoom*100)+'%';$('#docTitle').textContent=state.projectName}
$('#markupFilter').oninput=renderTable;
document.addEventListener('pointerdown',e=>{if(e.target.closest('.palette,.contextMenu,[data-palette],#btnProperties,#mainToolbar'))return;closePalettes();$('#contextMenu').classList.add('hidden')});document.addEventListener('click',e=>{if(!e.target.closest('#contextMenu'))$('#contextMenu').classList.add('hidden')});
window.addEventListener('keydown',e=>{const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag)&&document.activeElement!==$('#inlineEditor'))return;if(e.code==='Space'&&!e.repeat&&!state.editing){state.previousTool=state.tool;setTool('hand');e.preventDefault()}if(e.ctrlKey&&(e.key==='='||e.key==='+')){setZoom(state.zoom*1.25);e.preventDefault()}else if(e.ctrlKey&&e.key==='-'){setZoom(state.zoom/1.25);e.preventDefault()}else if(e.ctrlKey&&e.key==='0'){fitPage();e.preventDefault()}else if(e.ctrlKey&&e.key==='1'){setZoom(1);e.preventDefault()}else if(e.ctrlKey&&e.key==='2'){fitWidth();e.preventDefault()}else if(!e.ctrlKey&&!e.altKey&&!state.editing){if(e.key.toLowerCase()==='h')setTool('hand');if(e.key.toLowerCase()==='v')setTool('select');if(e.key.toLowerCase()==='z')setTool('zoom')}if(e.key==='Escape'){if(state.editing)finishInlineEdit();else{closePalettes();$('#contextMenu').classList.add('hidden');finishPolyDraft(false);setTool('hand')}}if(e.key==='Delete'&&state.selected&&!state.editing)deleteSelected()});window.addEventListener('keyup',e=>{if(e.code==='Space'&&state.previousTool){const t=state.previousTool;state.previousTool=null;setTool(t)}});window.addEventListener('resize',()=>{closePalettes();requestAnimationFrame(()=>state.pdfMode?null:fitPage())});
